import{Pinion,Tape,encodeSeed,decodeSeed,base64,unbase64,unpackBits,canonical,need}from'./core.js';
export class Machine{
 constructor(checkpoint={role:'pinion',data:base64(encodeSeed(new Pinion()))}){need(['pinion','tape'].includes(checkpoint.role),'Unknown operator role');this.role=checkpoint.role;if(this.role==='pinion')this.kernel=decodeSeed(unbase64(checkpoint.data));else{this.kernel=new Tape(checkpoint.data);need(Number.isInteger(checkpoint.data.tick??0)&&(checkpoint.data.tick??0)>=0&&(checkpoint.data.tick??0)<=0xffffffff,'Invalid tape clock');this.kernel.tick=checkpoint.data.tick??0;this.kernel.status=checkpoint.data.status??'READY';need(['READY','ACCEPT','HALT','INVALID','DEFER'].includes(this.kernel.status),'Invalid tape status');this.tapeWindow();}}
 tapeWindow(){if(this.role==='tape')need(this.kernel.head>=-2048&&this.kernel.head<2048&&[...this.kernel.cells.keys()].every(h=>h>=-2048&&h<2048),'DEFER: tape exceeds device window');}
 checkpoint(){return{role:this.role,data:this.role==='pinion'?base64(encodeSeed(this.kernel)):this.kernel.snapshot()};}
 clone(){return new Machine(this.checkpoint());}
 genes(g){need(g&&['pinion','tape'].includes(g.role),'Unknown gene role');if(g.role!==this.role){this.role=g.role;this.kernel=g.role==='pinion'?new Pinion(g):new Tape(g);}else this.kernel.setGenes(g);this.tapeWindow();}
 async step(bits,gpu){if(this.role==='pinion')return gpu?gpu.pinion(this.kernel,bits):bits.map(b=>this.kernel.step(b));if(gpu){const before=this.kernel.tick,result=await gpu.tape(this.kernel,bits.length);return Array.from({length:this.kernel.tick-before},(_,i)=>{const t=Array.from(result.trace.slice(4*i,4*i+4));t[1]=(t[1]|0)-2048;return t;});}const out=[];for(const _ of bits){if(this.kernel.q!==this.kernel.halt){const rule=this.kernel.rules.get(this.kernel.q*256+(this.kernel.cells.get(this.kernel.head)??0));need(rule,'Missing tape transition');need(this.kernel.head+rule[1]>=-2048&&this.kernel.head+rule[1]<2048,'DEFER: tape budget exhausted');}const t=this.kernel.step();if(t)out.push(t);else break;}return out;}
 async apply(batch,gpu){const candidate=this.clone(),cpu=this.clone(),traces=[];for(const event of batch){if(event.kind==='idle')continue;if(event.kind==='genes'){candidate.genes(event.genes);cpu.genes(event.genes);}else{const bits=unpackBits(event),expected=await cpu.step(bits),actual=await candidate.step(bits,gpu);need(canonical(actual)===canonical(expected),'Hardware trace differs from integer reference');traces.push(...actual);}}if(candidate.role==='tape'&&candidate.kernel.q===candidate.kernel.halt)candidate.kernel.status='HALT';if(cpu.role==='tape'&&cpu.kernel.q===cpu.kernel.halt)cpu.kernel.status='HALT';need(canonical(candidate.checkpoint())===canonical(cpu.checkpoint()),'Hardware checkpoint differs from integer reference');this.role=candidate.role;this.kernel=candidate.kernel;return{checkpoint:this.checkpoint(),trace:traces};}
}
